const SDK='https://www.gstatic.com/firebasejs/12.4.0/';
export async function connectFirebase(config,onUser){
 const [{initializeApp,getApps},{getAuth,onAuthStateChanged,signInWithEmailAndPassword,createUserWithEmailAndPassword,signOut,sendPasswordResetEmail},{getFirestore,doc,getDoc,setDoc,collection,getDocs,writeBatch,deleteDoc}]=await Promise.all([import(SDK+'firebase-app.js'),import(SDK+'firebase-auth.js'),import(SDK+'firebase-firestore.js')]);
 const app=getApps().find(a=>a.options.projectId===config.projectId)||initializeApp(config,config.projectId),auth=getAuth(app),db=getFirestore(app);
 const client={get user(){return auth.currentUser;},pendingState:null,
 async loadState(){const snap=await getDoc(doc(db,'users',auth.currentUser.uid,'data','bloom'));return snap.exists()?snap.data().state:null;},
 async saveState(state){const userId=auth.currentUser.uid;await setDoc(doc(db,'users',userId,'data','bloom'),{state,updatedAt:new Date().toISOString()});const reminders=collection(db,'users',userId,'reminders'),existing=await getDocs(reminders);const upcoming=state.settings.notifications?state.tasks.filter(t=>!t.done&&t.reminder).map(t=>({...t,dueAt:new Date(`${t.date}T${t.reminder}`).getTime()})).filter(t=>t.dueAt>Date.now()-10*60*1000):[];const valid=new Set(upcoming.map(t=>t.id));let batch=writeBatch(db),ops=0;for(const d of existing.docs){if(!valid.has(d.id)){batch.delete(d.ref);ops++;}if(ops===400){await batch.commit();batch=writeBatch(db);ops=0;}}for(const t of upcoming){batch.set(doc(reminders,t.id),{title:t.title,dueAt:t.dueAt,taskId:t.id,url:location.origin});ops++;if(ops===400){await batch.commit();batch=writeBatch(db);ops=0;}}if(ops)await batch.commit();},
 authenticate:(email,password,create)=>create?createUserWithEmailAndPassword(auth,email,password):signInWithEmailAndPassword(auth,email,password),resetPassword:email=>sendPasswordResetEmail(auth,email),
 async signOut(){try{const key=localStorage.getItem('bloom-device-id');if(key&&auth.currentUser)await deleteDoc(doc(db,'users',auth.currentUser.uid,'devices',key));}catch{}await signOut(auth);},
 async enableMessaging(vapidKey){const {getMessaging,getToken,isSupported}=await import(SDK+'firebase-messaging.js');if(!await isSupported())throw Error('Messaging is not supported.');const reg=await navigator.serviceWorker.ready;const token=await getToken(getMessaging(app),{vapidKey,serviceWorkerRegistration:reg});if(!token)throw Error('No notification token.');let id=localStorage.getItem('bloom-device-id');if(!id){id=crypto.randomUUID();localStorage.setItem('bloom-device-id',id);}await setDoc(doc(db,'users',auth.currentUser.uid,'devices',id),{token,updatedAt:Date.now()});return token;}
 };
 const unsubscribe=onAuthStateChanged(auth,user=>setTimeout(()=>onUser(user),0));client.dispose=unsubscribe;return client;
}
